from pathlib import Path

path = Path('/home/ubuntu/alfurqan-school-management/client/src/pages/Home.tsx')
source = path.read_text()
start = source.index('function AccountantDashboard(')
end = source.index('function ParentDashboard(', start)
new = '''function AccountantDashboard({ user }: { user: NonNullable<ReturnType<typeof useAuth>["user"]> }) { const payments = trpc.school.payments.useQuery(); const invoices = trpc.school.invoices.useQuery(); const studentsQuery = trpc.school.students.useQuery(); const receiptSettingsQuery = trpc.school.schoolSettings.useQuery(); const [recordOpen, setRecordOpen] = useState(false); const [studentId, setStudentId] = useState(""); const [amount, setAmount] = useState(""); const [reference, setReference] = useState(""); const [method, setMethod] = useState<"bank_transfer" | "paystack">("bank_transfer"); const [proofDetails, setProofDetails] = useState(""); const studentPayment = trpc.school.createPayment.useMutation({ onSuccess: () => { toast.success("Payment recorded and queued for verification"); setRecordOpen(false); setStudentId(""); setAmount(""); setReference(""); setProofDetails(""); void payments.refetch(); } , onError: error => toast.error(error.message) }); const verify = trpc.school.verifyBankTransfer.useMutation({ onSuccess: result => { toast.success(result.status === "verified" ? `Payment verified · ${result.receiptNumber ?? "receipt assigned"}` : "Payment rejected"); void payments.refetch(); }, onError: error => toast.error(error.message) }); const totalVerified = (payments.data ?? []).filter(payment => payment.status === "verified").reduce((sum, payment) => sum + payment.amountKobo, 0); const pending = (payments.data ?? []).filter(payment => payment.status === "pending"); const outstandingInvoices = (invoices.data ?? []).filter(invoice => invoice.status !== "paid").reduce((sum, invoice) => sum + invoice.amountKobo, 0); const studentName = (id: number) => studentsQuery.data?.find(student => student.id === id)?.name ?? `Student #${id}`; const submitPayment = () => { const amountKobo = Math.round(Number(amount) * 100); if (!studentId || !Number.isInteger(amountKobo) || amountKobo <= 0 || reference.trim().length < 5) return toast.error("Select a student and enter a valid amount and reference"); studentPayment.mutate({ studentId: Number(studentId), reference: reference.trim(), method, amountKobo, proofDetails: proofDetails.trim() || undefined }); }; return <><div className="view-intro"><div><p className="eyebrow">Finance desk</p><h2 className="section-title large">Good morning, {user.name?.split(" ")[0] ?? "Accountant"}</h2><p className="muted">A live finance workspace for recording collections, reviewing bank evidence, and issuing verified receipts.</p></div><button className="primary-button" onClick={() => setRecordOpen(current => !current)}><Plus size={15} /> {recordOpen ? "Close payment form" : "Record payment"}</button></div>{recordOpen && <section className="surface intake-form account-form"><div className="intake-form-head"><div><h3>Record a student payment</h3><p className="muted">The payment remains pending until an authorized reviewer verifies it.</p></div><span className="form-required">Accountant workflow</span></div><div className="intake-grid"><label>Student<select value={studentId} onChange={event => setStudentId(event.target.value)}><option value="">Select student</option>{(studentsQuery.data ?? []).map(student => <option key={student.id} value={student.id}>{student.name} · {student.className}</option>)}</select></label><label>Amount (₦)<input inputMode="decimal" type="number" min="1" step="0.01" value={amount} onChange={event => setAmount(event.target.value)} placeholder="e.g. 85000" /></label><label>Reference<input value={reference} onChange={event => setReference(event.target.value)} placeholder="Bank or gateway reference" /></label><label>Method<select value={method} onChange={event => setMethod(event.target.value as "bank_transfer" | "paystack")}><option value="bank_transfer">Bank transfer</option><option value="paystack">Card / Paystack</option></select></label><label>Proof note <span className="muted">(optional)</span><input value={proofDetails} onChange={event => setProofDetails(event.target.value)} placeholder="Teller number or confirmation note" /></label></div><div className="intake-actions"><button className="primary-button" disabled={studentPayment.isPending} onClick={submitPayment}>{studentPayment.isPending ? "Saving payment..." : "Save payment"}</button></div></section>}<div className="role-stats"><RoleStat label="Verified this term" value={`₦${(totalVerified / 100).toLocaleString()}`} detail={`${(payments.data ?? []).filter(payment => payment.status === "verified").length} verified transactions`} tone="tone-sage" /><RoleStat label="Awaiting verification" value={`${pending.length}`} detail="Bank transfers and card records" tone="tone-amber" /><RoleStat label="Outstanding invoices" value={`₦${(outstandingInvoices / 100).toLocaleString()}`} detail={`${(invoices.data ?? []).filter(invoice => invoice.status !== "paid").length} unpaid invoice records`} tone="tone-plum" /></div><div className="role-grid"><section className="surface role-panel"><SectionHeading title="Verification queue" subtitle="Review each payment individually" />{payments.isLoading ? <p className="empty-state">Loading payment queue...</p> : !pending.length ? <p className="empty-state">No pending payments require verification.</p> : <div className="module-list">{pending.map(payment => <div className="module-row" key={payment.id}><div><b>{studentName(payment.studentId)}</b><p>{payment.reference} · {payment.method.replace("_", " ")} · ₦{(payment.amountKobo / 100).toLocaleString()}</p><small className="muted">{payment.proofDetails || "No proof note supplied"}</small></div><div className="row-actions"><button className="filter-button" disabled={verify.isPending} onClick={() => verify.mutate({ id: payment.id, status: "verified" })}>Verify</button><button className="filter-button danger-button" disabled={verify.isPending} onClick={() => verify.mutate({ id: payment.id, status: "rejected" })}>Reject</button></div></div>)}</div>}</section><section className="surface role-panel"><SectionHeading title="Recent transactions" subtitle="Live records from the database" />{payments.isLoading ? <p className="empty-state">Loading payments...</p> : !(payments.data ?? []).length ? <p className="empty-state">No payments have been recorded yet.</p> : <div className="module-list">{(payments.data ?? []).slice(0, 8).map(payment => <div className="module-row" key={payment.id}><div><b>{studentName(payment.studentId)}</b><p>{payment.reference} · {payment.method.replace("_", " ")} · ₦{(payment.amountKobo / 100).toLocaleString()}</p></div><div className="row-actions"><span className={`status ${payment.status === "verified" ? "active" : payment.status === "rejected" ? "pending" : "pending"}`}><i />{payment.status}</span>{payment.status === "verified" && <button className="text-action" onClick={() => openPaymentReceipt({ ...payment, studentName: studentName(payment.studentId), admissionNo: studentsQuery.data?.find(student => student.id === payment.studentId)?.admissionNo }, receiptSettingsQuery.data ?? defaultReceiptSettings)}>Receipt</button>}</div></div>)}</div>}</section></div></>; }
'''
source = source[:start] + new + source[end:]
path.write_text(source)
print('Accountant dashboard upgraded')
